def merge(T):
    u = json.load(open(P))
    for k, v in T.items():
        cur = u.get(k, {})
        for i, l in enumerate(L):
            if not cur.get(l): cur[l] = v[i]
        u[k] = cur
    json.dump(u, open(P, 'w'), ensure_ascii=False, indent=1)
    return len(T)
if __name__ == '__main__':
    print('merged', merge(T), merge(T2), merge(T3))
